CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. 320 chars is the RFC 5321 maximum for an address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name the picker and driver see on the tote label.
	"full_name" VARCHAR(160) NOT NULL,
	-- E.164 number. The picker texts it when something is out of stock and the preference says contact me.
	"phone" VARCHAR(32) NOT NULL,
	-- allow_similar | best_available | refund_item | contact_me. Copied onto every order line at checkout so a preference change never rewrites a live order.
	"default_substitution_preference" VARCHAR(24) NOT NULL DEFAULT 'allow_similar',
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last profile change.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'A household that shops. The substitution default lives here because it is a standing instruction, but it is only ever read once, at checkout.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."email" IS 'Login identity. 320 chars is the RFC 5321 maximum for an address.';
COMMENT ON COLUMN "customers"."full_name" IS 'Name the picker and driver see on the tote label.';
COMMENT ON COLUMN "customers"."phone" IS 'E.164 number. The picker texts it when something is out of stock and the preference says contact me.';
COMMENT ON COLUMN "customers"."default_substitution_preference" IS 'allow_similar | best_available | refund_item | contact_me. Copied onto every order line at checkout so a preference change never rewrites a live order.';
COMMENT ON COLUMN "customers"."created_at" IS 'Signup time.';
COMMENT ON COLUMN "customers"."updated_at" IS 'Last profile change.';

CREATE TABLE IF NOT EXISTS "stores" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Banner and branch, e.g. Greenline Market Fulton Street.
	"name" VARCHAR(160) NOT NULL,
	-- URL segment for the store page.
	"slug" VARCHAR(180) NOT NULL UNIQUE,
	-- Street address pickers and drivers navigate to.
	"address_line" VARCHAR(300) NOT NULL,
	-- City, used to match a shopper to nearby stores.
	"city" VARCHAR(120) NOT NULL,
	-- ISO 3166-1 alpha-2 code. Drives tax rules and unit conventions.
	"country_code" CHAR(2) NOT NULL,
	-- ISO 4217 currency every price in this store is quoted in.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- IANA zone. Delivery windows are local wall-clock times; storing them as instants is how a window drifts an hour twice a year.
	"timezone" VARCHAR(64) NOT NULL,
	-- kg | lb. Display only: all weights are stored in grams regardless, because mixing units in the database is how a customer gets billed 2.2x.
	"weight_unit" VARCHAR(8) NOT NULL DEFAULT 'kg',
	-- False while a branch is closed or being onboarded.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Onboarding time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "stores" IS 'A physical shop that is picked from. Everything commercial hangs off the store rather than the chain, because price, range and availability differ branch to branch.';
COMMENT ON COLUMN "stores"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "stores"."name" IS 'Banner and branch, e.g. Greenline Market Fulton Street.';
COMMENT ON COLUMN "stores"."slug" IS 'URL segment for the store page.';
COMMENT ON COLUMN "stores"."address_line" IS 'Street address pickers and drivers navigate to.';
COMMENT ON COLUMN "stores"."city" IS 'City, used to match a shopper to nearby stores.';
COMMENT ON COLUMN "stores"."country_code" IS 'ISO 3166-1 alpha-2 code. Drives tax rules and unit conventions.';
COMMENT ON COLUMN "stores"."currency_code" IS 'ISO 4217 currency every price in this store is quoted in.';
COMMENT ON COLUMN "stores"."timezone" IS 'IANA zone. Delivery windows are local wall-clock times; storing them as instants is how a window drifts an hour twice a year.';
COMMENT ON COLUMN "stores"."weight_unit" IS 'kg | lb. Display only: all weights are stored in grams regardless, because mixing units in the database is how a customer gets billed 2.2x.';
COMMENT ON COLUMN "stores"."is_active" IS 'False while a branch is closed or being onboarded.';
COMMENT ON COLUMN "stores"."created_at" IS 'Onboarding time.';

CREATE INDEX "idx_stores_city_active"
ON "stores" ("city", "is_active");

CREATE TABLE IF NOT EXISTS "products" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Global trade item number, the barcode. Null for loose produce, which has no barcode and is the reason this column is nullable.
	"gtin" VARCHAR(14) UNIQUE,
	-- Product name shown in search results.
	"name" VARCHAR(220) NOT NULL,
	-- Brand name. Null for own-label and loose goods.
	"brand" VARCHAR(120),
	-- Materialised category path, e.g. produce/fruit/apples. A path column rather than a tree table because grocery taxonomies are shallow, wide and mostly used as a breadcrumb filter.
	"category_path" VARCHAR(300) NOT NULL,
	-- each | weight. The single most consequential column here: it decides whether a line is billed on count or on what the scale said.
	"sold_by" VARCHAR(12) NOT NULL DEFAULT 'each',
	-- each | kg | lb. The unit a price is quoted in. A weight-sold item priced per kg still shows an estimated pack price in the app.
	"price_unit" VARCHAR(8) NOT NULL DEFAULT 'each',
	-- Typical weight of one piece, e.g. a banana. Used to turn a request for 6 bananas into an estimated charge before anyone has weighed anything. Null for pre-packed goods.
	"average_unit_weight_grams" INTEGER,
	-- Forces an ID check at handover. A basket containing one of these cannot be left on a doorstep.
	"is_age_restricted" BOOLEAN NOT NULL DEFAULT false,
	-- When the product entered the catalogue.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "products" IS 'The chain-wide description of a thing that can be bought. It deliberately has no price and no stock: those are per store, and a single national price column is the first thing that breaks when the second branch opens.';
COMMENT ON COLUMN "products"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "products"."gtin" IS 'Global trade item number, the barcode. Null for loose produce, which has no barcode and is the reason this column is nullable.';
COMMENT ON COLUMN "products"."name" IS 'Product name shown in search results.';
COMMENT ON COLUMN "products"."brand" IS 'Brand name. Null for own-label and loose goods.';
COMMENT ON COLUMN "products"."category_path" IS 'Materialised category path, e.g. produce/fruit/apples. A path column rather than a tree table because grocery taxonomies are shallow, wide and mostly used as a breadcrumb filter.';
COMMENT ON COLUMN "products"."sold_by" IS 'each | weight. The single most consequential column here: it decides whether a line is billed on count or on what the scale said.';
COMMENT ON COLUMN "products"."price_unit" IS 'each | kg | lb. The unit a price is quoted in. A weight-sold item priced per kg still shows an estimated pack price in the app.';
COMMENT ON COLUMN "products"."average_unit_weight_grams" IS 'Typical weight of one piece, e.g. a banana. Used to turn a request for 6 bananas into an estimated charge before anyone has weighed anything. Null for pre-packed goods.';
COMMENT ON COLUMN "products"."is_age_restricted" IS 'Forces an ID check at handover. A basket containing one of these cannot be left on a doorstep.';
COMMENT ON COLUMN "products"."created_at" IS 'When the product entered the catalogue.';

CREATE INDEX "idx_products_category_path"
ON "products" ("category_path");
CREATE INDEX "idx_products_sold_by"
ON "products" ("sold_by");

CREATE TABLE IF NOT EXISTS "store_products" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Branch this listing belongs to.
	"store_id" BIGINT NOT NULL,
	-- Product being listed.
	"product_id" BIGINT NOT NULL,
	-- Physical location in the shop, e.g. 14B. It is what makes a picking task walkable in one pass instead of three laps.
	"aisle" VARCHAR(40),
	-- Current price per price_unit, in minor units. Integers only; never float money.
	"price_cents" INTEGER NOT NULL,
	-- Previous price, shown struck through during a promotion. Null when not on offer.
	"was_price_cents" INTEGER,
	-- ISO 4217 currency for price_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Whether the shop currently sells it at all, as opposed to being temporarily out of stock.
	"is_available" BOOLEAN NOT NULL DEFAULT true,
	-- Preference order when this listing is offered as a substitute for another. Null means never suggest it automatically.
	"substitution_rank" INTEGER,
	-- Last price or availability change. Feeds the price-changed-since-you-added-it banner.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "store_products" IS 'One product in one shop, with its price and its aisle. This is the row everything downstream actually points at, because a basket line means nothing without knowing which branch it will be picked from.';
COMMENT ON COLUMN "store_products"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "store_products"."store_id" IS 'Branch this listing belongs to.';
COMMENT ON COLUMN "store_products"."product_id" IS 'Product being listed.';
COMMENT ON COLUMN "store_products"."aisle" IS 'Physical location in the shop, e.g. 14B. It is what makes a picking task walkable in one pass instead of three laps.';
COMMENT ON COLUMN "store_products"."price_cents" IS 'Current price per price_unit, in minor units. Integers only; never float money.';
COMMENT ON COLUMN "store_products"."was_price_cents" IS 'Previous price, shown struck through during a promotion. Null when not on offer.';
COMMENT ON COLUMN "store_products"."currency_code" IS 'ISO 4217 currency for price_cents.';
COMMENT ON COLUMN "store_products"."is_available" IS 'Whether the shop currently sells it at all, as opposed to being temporarily out of stock.';
COMMENT ON COLUMN "store_products"."substitution_rank" IS 'Preference order when this listing is offered as a substitute for another. Null means never suggest it automatically.';
COMMENT ON COLUMN "store_products"."updated_at" IS 'Last price or availability change. Feeds the price-changed-since-you-added-it banner.';

CREATE UNIQUE INDEX "uq_store_products_store_product"
ON "store_products" ("store_id", "product_id");
CREATE INDEX "idx_store_products_store_aisle"
ON "store_products" ("store_id", "aisle");

CREATE TABLE IF NOT EXISTS "inventory_counts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Listing being counted.
	"store_product_id" BIGINT NOT NULL,
	-- When the count was taken. Counts are timestamped rather than overwritten, so you can see how fast a line depletes on a Saturday.
	"counted_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- pos_feed | picker_report | stock_take | supplier_delivery. A picker saying the shelf is empty is far more current than last night file, and far less trustworthy than a stock take.
	"source" VARCHAR(20) NOT NULL,
	-- Units or kilograms believed present. Numeric rather than integer because loose goods are counted by weight. Null when the source only reports presence or absence.
	"quantity_on_shelf" NUMERIC(10,3),
	-- Explicit empty-shelf signal. Separate from a zero quantity, because most sources can tell you it is gone without telling you how much was there.
	"is_out_of_stock" BOOLEAN NOT NULL DEFAULT false,
	-- low | medium | high. Drives whether search still shows the item and whether the app warns that it may be substituted.
	"confidence" VARCHAR(12) NOT NULL DEFAULT 'medium',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "inventory_counts" IS 'An observation of stock, not a running balance. Grocery inventory is never accurate enough to decrement reliably, so this table keeps timestamped sightings from several sources and the app reconciles them by recency and confidence.';
COMMENT ON COLUMN "inventory_counts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "inventory_counts"."store_product_id" IS 'Listing being counted.';
COMMENT ON COLUMN "inventory_counts"."counted_at" IS 'When the count was taken. Counts are timestamped rather than overwritten, so you can see how fast a line depletes on a Saturday.';
COMMENT ON COLUMN "inventory_counts"."source" IS 'pos_feed | picker_report | stock_take | supplier_delivery. A picker saying the shelf is empty is far more current than last night file, and far less trustworthy than a stock take.';
COMMENT ON COLUMN "inventory_counts"."quantity_on_shelf" IS 'Units or kilograms believed present. Numeric rather than integer because loose goods are counted by weight. Null when the source only reports presence or absence.';
COMMENT ON COLUMN "inventory_counts"."is_out_of_stock" IS 'Explicit empty-shelf signal. Separate from a zero quantity, because most sources can tell you it is gone without telling you how much was there.';
COMMENT ON COLUMN "inventory_counts"."confidence" IS 'low | medium | high. Drives whether search still shows the item and whether the app warns that it may be substituted.';

CREATE INDEX "idx_inventory_counts_listing_time"
ON "inventory_counts" ("store_product_id", "counted_at");

CREATE TABLE IF NOT EXISTS "delivery_windows" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Branch that fulfils the window. Capacity is a property of one shop staffing, not of the chain.
	"store_id" BIGINT NOT NULL,
	-- Local calendar date of the window. A date rather than a timestamp, because a slot belongs to a day in the store timezone.
	"window_date" DATE NOT NULL,
	-- Local start of the slot, e.g. 17:00.
	"starts_at" TIME NOT NULL,
	-- Local end of the slot, e.g. 19:00.
	"ends_at" TIME NOT NULL,
	-- How many orders the shop can pick and drive in this slot. The hard limit checkout enforces.
	"capacity_orders" INTEGER NOT NULL,
	-- Orders already booked. Incremented in the same transaction that creates the order, so two shoppers cannot both take the last slot.
	"reserved_orders" INTEGER NOT NULL DEFAULT 0,
	-- Delivery fee for this slot, in minor units. Quiet slots are cheaper, which is the only lever a grocer has to smooth demand.
	"fee_cents" INTEGER NOT NULL DEFAULT 0,
	-- ISO 4217 currency for fee_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Manual close, used when a van breaks or snow shuts the road. Deliberately independent of capacity: a shop sometimes wants to stop selling a slot it could still fill.
	"is_open" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "delivery_windows" IS 'A bookable slot with its own capacity counter. Availability is capacity_orders minus reserved_orders, checked and decremented inside the checkout transaction, which is what stops overbooking a Saturday evening.';
COMMENT ON COLUMN "delivery_windows"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "delivery_windows"."store_id" IS 'Branch that fulfils the window. Capacity is a property of one shop staffing, not of the chain.';
COMMENT ON COLUMN "delivery_windows"."window_date" IS 'Local calendar date of the window. A date rather than a timestamp, because a slot belongs to a day in the store timezone.';
COMMENT ON COLUMN "delivery_windows"."starts_at" IS 'Local start of the slot, e.g. 17:00.';
COMMENT ON COLUMN "delivery_windows"."ends_at" IS 'Local end of the slot, e.g. 19:00.';
COMMENT ON COLUMN "delivery_windows"."capacity_orders" IS 'How many orders the shop can pick and drive in this slot. The hard limit checkout enforces.';
COMMENT ON COLUMN "delivery_windows"."reserved_orders" IS 'Orders already booked. Incremented in the same transaction that creates the order, so two shoppers cannot both take the last slot.';
COMMENT ON COLUMN "delivery_windows"."fee_cents" IS 'Delivery fee for this slot, in minor units. Quiet slots are cheaper, which is the only lever a grocer has to smooth demand.';
COMMENT ON COLUMN "delivery_windows"."currency_code" IS 'ISO 4217 currency for fee_cents.';
COMMENT ON COLUMN "delivery_windows"."is_open" IS 'Manual close, used when a van breaks or snow shuts the road. Deliberately independent of capacity: a shop sometimes wants to stop selling a slot it could still fill.';

CREATE UNIQUE INDEX "uq_delivery_windows_store_date_start"
ON "delivery_windows" ("store_id", "window_date", "starts_at");
CREATE INDEX "idx_delivery_windows_date_open"
ON "delivery_windows" ("window_date", "is_open");

CREATE TABLE IF NOT EXISTS "baskets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner once known. Null for an anonymous session browsing prices.
	"customer_id" BIGINT,
	-- Branch the basket is priced against. Changing store re-prices the whole basket and can drop lines, which is why it is a column here rather than chosen at checkout.
	"store_id" BIGINT NOT NULL,
	-- Anonymous basket identity in a cookie, merged into the customer basket at sign-in.
	"session_token" VARCHAR(64) NOT NULL UNIQUE,
	-- Basket creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last line change. Drives abandoned-basket reminders.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "baskets" IS 'A live basket. It is disposable: once an order is placed nothing reads it again, and it stores no prices so a price change is visible the moment the shopper reopens the app.';
COMMENT ON COLUMN "baskets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "baskets"."customer_id" IS 'Owner once known. Null for an anonymous session browsing prices.';
COMMENT ON COLUMN "baskets"."store_id" IS 'Branch the basket is priced against. Changing store re-prices the whole basket and can drop lines, which is why it is a column here rather than chosen at checkout.';
COMMENT ON COLUMN "baskets"."session_token" IS 'Anonymous basket identity in a cookie, merged into the customer basket at sign-in.';
COMMENT ON COLUMN "baskets"."created_at" IS 'Basket creation time.';
COMMENT ON COLUMN "baskets"."updated_at" IS 'Last line change. Drives abandoned-basket reminders.';

CREATE TABLE IF NOT EXISTS "basket_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent basket.
	"basket_id" BIGINT NOT NULL,
	-- Listing added.
	"store_product_id" BIGINT NOT NULL,
	-- Units for a counted item, kilograms for a weight-sold one. Numeric with three decimals because 0.350 kg of olives is a normal request.
	"requested_quantity" NUMERIC(10,3) NOT NULL DEFAULT 1,
	-- Per-line override of the customer default. Null falls back to the customer setting; people accept a different brand of pasta but not a different birthday cake.
	"substitution_preference" VARCHAR(24),
	-- Free text, e.g. green bananas please. Read by a human, never parsed.
	"note_to_picker" VARCHAR(200),
	-- When the line was added.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "basket_items" IS 'A basket line. It carries no price at all: the basket re-reads the live listing on every render, which is how a shopper sees a price change before committing to it.';
COMMENT ON COLUMN "basket_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "basket_items"."basket_id" IS 'Parent basket.';
COMMENT ON COLUMN "basket_items"."store_product_id" IS 'Listing added.';
COMMENT ON COLUMN "basket_items"."requested_quantity" IS 'Units for a counted item, kilograms for a weight-sold one. Numeric with three decimals because 0.350 kg of olives is a normal request.';
COMMENT ON COLUMN "basket_items"."substitution_preference" IS 'Per-line override of the customer default. Null falls back to the customer setting; people accept a different brand of pasta but not a different birthday cake.';
COMMENT ON COLUMN "basket_items"."note_to_picker" IS 'Free text, e.g. green bananas please. Read by a human, never parsed.';
COMMENT ON COLUMN "basket_items"."added_at" IS 'When the line was added.';

CREATE UNIQUE INDEX "uq_basket_items_basket_listing"
ON "basket_items" ("basket_id", "store_product_id");

CREATE TABLE IF NOT EXISTS "pickers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Home branch. Pickers know one shop layout, and routing quality depends on it.
	"store_id" BIGINT NOT NULL,
	-- Name shown to the customer on substitution messages.
	"full_name" VARCHAR(160) NOT NULL,
	-- E.164 number, also the login identity for the handheld.
	"phone" VARCHAR(32) NOT NULL UNIQUE,
	-- off_shift | available | picking | on_break.
	"status" VARCHAR(16) NOT NULL DEFAULT 'off_shift',
	-- Rolling pick rate. Used to size a task to the time left in a window, not to rank people.
	"items_per_hour" NUMERIC(6,2),
	-- Start date.
	"onboarded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pickers" IS 'A person who walks the shop with a handheld. Kept separate from drivers because picking and delivery are scheduled against different constraints and are often different companies.';
COMMENT ON COLUMN "pickers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pickers"."store_id" IS 'Home branch. Pickers know one shop layout, and routing quality depends on it.';
COMMENT ON COLUMN "pickers"."full_name" IS 'Name shown to the customer on substitution messages.';
COMMENT ON COLUMN "pickers"."phone" IS 'E.164 number, also the login identity for the handheld.';
COMMENT ON COLUMN "pickers"."status" IS 'off_shift | available | picking | on_break.';
COMMENT ON COLUMN "pickers"."items_per_hour" IS 'Rolling pick rate. Used to size a task to the time left in a window, not to rank people.';
COMMENT ON COLUMN "pickers"."onboarded_at" IS 'Start date.';

CREATE INDEX "idx_pickers_store_status"
ON "pickers" ("store_id", "status");

CREATE TABLE IF NOT EXISTS "orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who ordered.
	"customer_id" BIGINT NOT NULL,
	-- Branch fulfilling it.
	"store_id" BIGINT NOT NULL,
	-- Basket it came from, kept for funnel analysis. Nullable so baskets can be reaped on a schedule.
	"basket_id" BIGINT,
	-- Slot booked. Required: a grocery order without a slot has nowhere to go.
	"delivery_window_id" BIGINT NOT NULL,
	-- Human reference on the tote label and in support conversations.
	"order_code" VARCHAR(16) NOT NULL UNIQUE,
	-- placed | picking | picked | out_for_delivery | delivered | cancelled.
	"status" VARCHAR(24) NOT NULL DEFAULT 'placed',
	-- Frozen copy of the dropoff address written once at checkout. Never a foreign key, or correcting a saved address would rewrite where last week shopping went.
	"delivery_address" JSON NOT NULL,
	-- Amount held on the card at checkout, computed from estimated weights plus a tolerance. This is a hold, not a charge.
	"authorised_total_cents" INTEGER NOT NULL,
	-- Amount actually taken after picking, from real weights and real substitutions. Null until the order is picked. The gap between the two columns is the entire reason weight pricing is hard.
	"captured_total_cents" INTEGER,
	-- ISO 4217 currency for every amount on this order.
	"currency_code" CHAR(3) NOT NULL,
	-- Slot fee snapshotted from the window, because window pricing changes as slots fill.
	"delivery_fee_cents" INTEGER NOT NULL DEFAULT 0,
	-- Checkout completion.
	"placed_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When picking finished and the final total was computed.
	"picked_at" TIMESTAMP,
	-- Handover time.
	"delivered_at" TIMESTAMP,
	-- Set on cancellation. The row is kept, because a released authorisation still has to be explained.
	"cancelled_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "orders" IS 'One shop for one household in one slot. Holding an authorised total and a captured total as separate columns is what lets the charge change between checkout and the doorstep without anyone rewriting history.';
COMMENT ON COLUMN "orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "orders"."customer_id" IS 'Who ordered.';
COMMENT ON COLUMN "orders"."store_id" IS 'Branch fulfilling it.';
COMMENT ON COLUMN "orders"."basket_id" IS 'Basket it came from, kept for funnel analysis. Nullable so baskets can be reaped on a schedule.';
COMMENT ON COLUMN "orders"."delivery_window_id" IS 'Slot booked. Required: a grocery order without a slot has nowhere to go.';
COMMENT ON COLUMN "orders"."order_code" IS 'Human reference on the tote label and in support conversations.';
COMMENT ON COLUMN "orders"."status" IS 'placed | picking | picked | out_for_delivery | delivered | cancelled.';
COMMENT ON COLUMN "orders"."delivery_address" IS 'Frozen copy of the dropoff address written once at checkout. Never a foreign key, or correcting a saved address would rewrite where last week shopping went.';
COMMENT ON COLUMN "orders"."authorised_total_cents" IS 'Amount held on the card at checkout, computed from estimated weights plus a tolerance. This is a hold, not a charge.';
COMMENT ON COLUMN "orders"."captured_total_cents" IS 'Amount actually taken after picking, from real weights and real substitutions. Null until the order is picked. The gap between the two columns is the entire reason weight pricing is hard.';
COMMENT ON COLUMN "orders"."currency_code" IS 'ISO 4217 currency for every amount on this order.';
COMMENT ON COLUMN "orders"."delivery_fee_cents" IS 'Slot fee snapshotted from the window, because window pricing changes as slots fill.';
COMMENT ON COLUMN "orders"."placed_at" IS 'Checkout completion.';
COMMENT ON COLUMN "orders"."picked_at" IS 'When picking finished and the final total was computed.';
COMMENT ON COLUMN "orders"."delivered_at" IS 'Handover time.';
COMMENT ON COLUMN "orders"."cancelled_at" IS 'Set on cancellation. The row is kept, because a released authorisation still has to be explained.';

CREATE INDEX "idx_orders_store_status"
ON "orders" ("store_id", "status");
CREATE INDEX "idx_orders_window"
ON "orders" ("delivery_window_id");
CREATE INDEX "idx_orders_customer_placed"
ON "orders" ("customer_id", "placed_at");

CREATE TABLE IF NOT EXISTS "order_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent order.
	"order_id" BIGINT NOT NULL,
	-- Listing ordered. Nullable so a delisted line can be removed without shredding order history.
	"store_product_id" BIGINT,
	-- Product name as it read at checkout, for the receipt.
	"name_snapshot" VARCHAR(220) NOT NULL,
	-- each | weight, snapshotted. The billing rule for this line must not change if the catalogue is later corrected.
	"sold_by" VARCHAR(12) NOT NULL,
	-- Price per price_unit at checkout, in minor units. Held for the whole order even if the shelf label changes overnight.
	"unit_price_cents" INTEGER NOT NULL,
	-- each | kg | lb, snapshotted alongside the price so the two can never disagree.
	"price_unit" VARCHAR(8) NOT NULL,
	-- What the customer asked for: units, or kilograms for loose goods.
	"requested_quantity" NUMERIC(10,3) NOT NULL,
	-- Expected weight at checkout, from the product average. Null for counted items. This is what the authorisation was calculated from.
	"estimated_weight_grams" INTEGER,
	-- What the picker actually put in the tote. Lower than requested when the shelf was short; null until picked.
	"picked_quantity" NUMERIC(10,3),
	-- What the scale said. The billed amount for a weight-sold line comes from this column and nothing else.
	"picked_weight_grams" INTEGER,
	-- Line amount at checkout, part of the authorisation.
	"estimated_total_cents" INTEGER NOT NULL,
	-- Line amount after picking, from picked quantity or picked weight. Null until picked; the sum of these is what gets captured.
	"final_total_cents" INTEGER,
	-- allow_similar | best_available | refund_item | contact_me, snapshotted from the basket. The picker sees this and nothing else.
	"substitution_preference" VARCHAR(24) NOT NULL,
	-- pending | picked | substituted | short_picked | unavailable.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Customer instruction carried through from the basket.
	"note_to_picker" VARCHAR(200),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "order_items" IS 'An order line that is written twice: once at checkout with estimates, once at the scale with reality. Keeping both sets of columns is what makes a receipt able to show you asked for 500 g and got 517 g.';
COMMENT ON COLUMN "order_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "order_items"."order_id" IS 'Parent order.';
COMMENT ON COLUMN "order_items"."store_product_id" IS 'Listing ordered. Nullable so a delisted line can be removed without shredding order history.';
COMMENT ON COLUMN "order_items"."name_snapshot" IS 'Product name as it read at checkout, for the receipt.';
COMMENT ON COLUMN "order_items"."sold_by" IS 'each | weight, snapshotted. The billing rule for this line must not change if the catalogue is later corrected.';
COMMENT ON COLUMN "order_items"."unit_price_cents" IS 'Price per price_unit at checkout, in minor units. Held for the whole order even if the shelf label changes overnight.';
COMMENT ON COLUMN "order_items"."price_unit" IS 'each | kg | lb, snapshotted alongside the price so the two can never disagree.';
COMMENT ON COLUMN "order_items"."requested_quantity" IS 'What the customer asked for: units, or kilograms for loose goods.';
COMMENT ON COLUMN "order_items"."estimated_weight_grams" IS 'Expected weight at checkout, from the product average. Null for counted items. This is what the authorisation was calculated from.';
COMMENT ON COLUMN "order_items"."picked_quantity" IS 'What the picker actually put in the tote. Lower than requested when the shelf was short; null until picked.';
COMMENT ON COLUMN "order_items"."picked_weight_grams" IS 'What the scale said. The billed amount for a weight-sold line comes from this column and nothing else.';
COMMENT ON COLUMN "order_items"."estimated_total_cents" IS 'Line amount at checkout, part of the authorisation.';
COMMENT ON COLUMN "order_items"."final_total_cents" IS 'Line amount after picking, from picked quantity or picked weight. Null until picked; the sum of these is what gets captured.';
COMMENT ON COLUMN "order_items"."substitution_preference" IS 'allow_similar | best_available | refund_item | contact_me, snapshotted from the basket. The picker sees this and nothing else.';
COMMENT ON COLUMN "order_items"."status" IS 'pending | picked | substituted | short_picked | unavailable.';
COMMENT ON COLUMN "order_items"."note_to_picker" IS 'Customer instruction carried through from the basket.';

CREATE INDEX "idx_order_items_order_status"
ON "order_items" ("order_id", "status");

CREATE TABLE IF NOT EXISTS "picking_tasks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order being picked.
	"order_id" BIGINT NOT NULL,
	-- Assigned picker. Null while the task is queued.
	"picker_id" BIGINT,
	-- Attempt number. A task handed to a second picker mid-shift is a new row, so pick time is never attributed to the wrong person.
	"sequence" INTEGER NOT NULL DEFAULT 1,
	-- queued | assigned | in_progress | completed | abandoned.
	"status" VARCHAR(20) NOT NULL DEFAULT 'queued',
	-- Lines in the task, snapshotted at assignment so a mid-pick cancellation does not make the workload look wrong afterwards.
	"item_count" INTEGER NOT NULL,
	-- Aisle-ordered line ids computed at assignment. Denormalised on purpose: recomputing a walking route on a handheld between every scan is a bad trade.
	"route_hint" JSON,
	-- When a picker accepted it.
	"assigned_at" TIMESTAMP,
	-- First scan.
	"started_at" TIMESTAMP,
	-- Last scan. Pick rate is item_count over completed minus started.
	"completed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "picking_tasks" IS 'One trolley walk through the shop. It is a separate row from the order because the same order can be reassigned, split across a shift change, or abandoned, and none of that should touch the customer record.';
COMMENT ON COLUMN "picking_tasks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "picking_tasks"."order_id" IS 'Order being picked.';
COMMENT ON COLUMN "picking_tasks"."picker_id" IS 'Assigned picker. Null while the task is queued.';
COMMENT ON COLUMN "picking_tasks"."sequence" IS 'Attempt number. A task handed to a second picker mid-shift is a new row, so pick time is never attributed to the wrong person.';
COMMENT ON COLUMN "picking_tasks"."status" IS 'queued | assigned | in_progress | completed | abandoned.';
COMMENT ON COLUMN "picking_tasks"."item_count" IS 'Lines in the task, snapshotted at assignment so a mid-pick cancellation does not make the workload look wrong afterwards.';
COMMENT ON COLUMN "picking_tasks"."route_hint" IS 'Aisle-ordered line ids computed at assignment. Denormalised on purpose: recomputing a walking route on a handheld between every scan is a bad trade.';
COMMENT ON COLUMN "picking_tasks"."assigned_at" IS 'When a picker accepted it.';
COMMENT ON COLUMN "picking_tasks"."started_at" IS 'First scan.';
COMMENT ON COLUMN "picking_tasks"."completed_at" IS 'Last scan. Pick rate is item_count over completed minus started.';

CREATE INDEX "idx_picking_tasks_picker_status"
ON "picking_tasks" ("picker_id", "status");
CREATE UNIQUE INDEX "uq_picking_tasks_order_sequence"
ON "picking_tasks" ("order_id", "sequence");

CREATE TABLE IF NOT EXISTS "substitutions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Line that could not be picked as asked.
	"order_item_id" BIGINT NOT NULL,
	-- Listing supplied instead. Null when the outcome was a refund rather than a swap, which is still a substitution event worth recording.
	"substitute_store_product_id" BIGINT,
	-- Name of what was supplied, as printed on the receipt. Null for a refund.
	"substitute_name_snapshot" VARCHAR(220),
	-- out_of_stock | damaged | expiring | wrong_size | customer_request.
	"reason" VARCHAR(24) NOT NULL,
	-- picker | customer | auto_rule. Whether a human chose it, the customer approved it over chat, or the ranking picked it. Refund rates differ enormously between the three.
	"decided_by" VARCHAR(16) NOT NULL,
	-- Signed difference against the original line. A more expensive substitute is normally absorbed rather than charged, and storing the number is how that policy is audited.
	"price_difference_cents" INTEGER NOT NULL DEFAULT 0,
	-- accepted | rejected | no_response. Null until the customer is asked; a rejection at the door becomes a refund, not an edit of this row.
	"customer_response" VARCHAR(16),
	-- When the swap was made in the aisle.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "substitutions" IS 'The record of what actually happened when the shelf was empty. It is a table rather than columns on the line because one line can be substituted, rejected at the door and refunded, and each of those is a separate fact.';
COMMENT ON COLUMN "substitutions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "substitutions"."order_item_id" IS 'Line that could not be picked as asked.';
COMMENT ON COLUMN "substitutions"."substitute_store_product_id" IS 'Listing supplied instead. Null when the outcome was a refund rather than a swap, which is still a substitution event worth recording.';
COMMENT ON COLUMN "substitutions"."substitute_name_snapshot" IS 'Name of what was supplied, as printed on the receipt. Null for a refund.';
COMMENT ON COLUMN "substitutions"."reason" IS 'out_of_stock | damaged | expiring | wrong_size | customer_request.';
COMMENT ON COLUMN "substitutions"."decided_by" IS 'picker | customer | auto_rule. Whether a human chose it, the customer approved it over chat, or the ranking picked it. Refund rates differ enormously between the three.';
COMMENT ON COLUMN "substitutions"."price_difference_cents" IS 'Signed difference against the original line. A more expensive substitute is normally absorbed rather than charged, and storing the number is how that policy is audited.';
COMMENT ON COLUMN "substitutions"."customer_response" IS 'accepted | rejected | no_response. Null until the customer is asked; a rejection at the door becomes a refund, not an edit of this row.';
COMMENT ON COLUMN "substitutions"."created_at" IS 'When the swap was made in the aisle.';

CREATE INDEX "idx_substitutions_order_item"
ON "substitutions" ("order_item_id");
CREATE INDEX "idx_substitutions_reason_created"
ON "substitutions" ("reason", "created_at");

